// Pure game rules. No network, DOM, or player information.
export const copy = value => JSON.parse(JSON.stringify(value));
const pick = (items, rng=Math.random) => items[Math.floor(rng()*items.length)];
export const LINES = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
export function ticResult(board){for(const line of LINES)if(board[line[0]]&&line.every(i=>board[i]===board[line[0]]))return{winner:board[line[0]],line};return board.every(Boolean)?{winner:'draw',line:[]}:null}
export function newTic(start=1){return{board:Array(9).fill(0),turn:start,result:null,moves:0}}
export function ticMove(state,index){if(state.result||!Number.isInteger(index)||index<0||index>8||state.board[index])return null;const s=copy(state);s.board[index]=s.turn;s.moves++;s.result=ticResult(s.board);if(!s.result)s.turn=3-s.turn;return s}
export function ticAI(s,level='gentle',rng=Math.random){const free=s.board.map((v,i)=>v?null:i).filter(i=>i!==null);if(!free.length||s.result)return null;if(level==='gentle')return pick(free,rng);const player=s.turn;function score(b,t,depth){const end=ticResult(b);if(end)return end.winner==='draw'?0:end.winner===player?10-depth:depth-10;const values=[];for(let i=0;i<9;i++)if(!b[i]){b[i]=t;values.push(score(b,3-t,depth+1));b[i]=0}return t===player?Math.max(...values):Math.min(...values)}const values=free.map(i=>{const b=[...s.board];b[i]=player;return score(b,3-player,0)});const best=Math.max(...values);return pick(free.filter((_,i)=>values[i]===best),rng)}

export function newDots(n=3,start=1){return{n,h:Array(n*(n+1)).fill(0),v:Array(n*(n+1)).fill(0),boxes:Array(n*n).fill(0),turn:start,result:null,moves:0}}
export function dotEdges(s){return ['h','v'].flatMap(axis=>s[axis].flatMap((v,i)=>v?[]:[{axis,index:i}]))}
export function boxEdgeCount(s,r,c){return [s.h[r*s.n+c],s.h[(r+1)*s.n+c],s.v[r*(s.n+1)+c],s.v[r*(s.n+1)+c+1]].filter(Boolean).length}
export function dotsMove(state,axis,index){if(state.result||!['h','v'].includes(axis)||!Number.isInteger(index)||index<0||index>=state[axis].length||state[axis][index])return null;const s=copy(state);s[axis][index]=s.turn;s.moves++;let scored=0;for(let r=0;r<s.n;r++)for(let c=0;c<s.n;c++){const i=r*s.n+c;if(!s.boxes[i]&&boxEdgeCount(s,r,c)===4){s.boxes[i]=s.turn;scored++}}if(s.boxes.every(Boolean)){const a=s.boxes.filter(p=>p===1).length,b=s.boxes.length-a;s.result={winner:a===b?'draw':a>b?1:2}}else if(!scored)s.turn=3-s.turn;s.lastScored=scored;return s}
export function dotsAI(s,level='gentle',rng=Math.random){const edges=dotEdges(s);if(!edges.length||s.result)return null;const options=edges.map(e=>({e,next:dotsMove(s,e.axis,e.index)}));const scoring=options.filter(x=>x.next.lastScored>0);if(scoring.length&&(level==='tricky'||rng()<.65))return pick(scoring,rng).e;if(level==='tricky'){const safe=options.filter(x=>{for(let r=0;r<s.n;r++)for(let c=0;c<s.n;c++)if(boxEdgeCount(x.next,r,c)===3)return false;return true});if(safe.length)return pick(safe,rng).e}return pick(edges,rng)}

export const owner = piece => Math.abs(piece);
export function newCheckers(start=1){const board=Array(64).fill(0);for(let r=0;r<8;r++)for(let c=0;c<8;c++)if((r+c)%2===1){if(r<3)board[r*8+c]=2;if(r>4)board[r*8+c]=1}const s={board,turn:start,forced:null,result:null,moves:0,quiet:0,repeats:{}};s.repeats[checkersKey(s)]=1;return s}
function checkersKey(s){return s.board.join(',')+'|'+s.turn}
function pieceMoves(board,index,jump){const piece=board[index];if(!piece)return [];const player=owner(piece),r=Math.floor(index/8),c=index%8;const dirs=piece<0?[-1,1]:player===1?[-1]:[1],out=[];for(const dr of dirs)for(const dc of [-1,1]){const nr=r+dr,nc=c+dc;if(nr<0||nr>7||nc<0||nc>7)continue;const near=nr*8+nc;if(!jump){if(!board[near])out.push({from:index,to:near,capture:null})}else{const jr=r+dr*2,jc=c+dc*2;if(jr>=0&&jr<8&&jc>=0&&jc<8&&board[near]&&owner(board[near])!==player&&!board[jr*8+jc])out.push({from:index,to:jr*8+jc,capture:near})}}return out}
export function checkersMoves(s){if(s.result)return [];if(s.forced!==null)return pieceMoves(s.board,s.forced,true);const pieces=s.board.flatMap((v,i)=>owner(v)===s.turn?[i]:[]),captures=pieces.flatMap(i=>pieceMoves(s.board,i,true));return captures.length?captures:pieces.flatMap(i=>pieceMoves(s.board,i,false))}
export function checkersMove(state,from,to){const move=checkersMoves(state).find(m=>m.from===from&&m.to===to);if(!move)return null;const s=copy(state),piece=s.board[from];s.board[from]=0;s.board[to]=piece;if(move.capture!==null)s.board[move.capture]=0;const crowned=piece>0&&((piece===1&&to<8)||(piece===2&&to>=56));if(crowned)s.board[to]=-piece;s.moves++;s.quiet=move.capture!==null||crowned?0:s.quiet+1;if(move.capture!==null&&!crowned&&pieceMoves(s.board,to,true).length){s.forced=to;return s}s.forced=null;s.turn=3-s.turn;if(!checkersMoves(s).length){s.result={winner:3-s.turn};return s}const key=checkersKey(s);s.repeats[key]=(s.repeats[key]||0)+1;if(s.quiet>=80||s.repeats[key]>=3)s.result={winner:'draw'};return s}
export function checkersAI(s,level='gentle',rng=Math.random){const moves=checkersMoves(s);if(!moves.length)return null;if(level==='gentle')return pick(moves,rng);const player=s.turn;function evaluate(st){if(st.result)return st.result.winner==='draw'?0:st.result.winner===player?10000:-10000;return st.board.reduce((total,p,i)=>{if(!p)return total;const row=Math.floor(i/8),col=i%8;const value=(p<0?175:100)+(p>0?(owner(p)===1?7-row:row)*4:0)+(col>1&&col<6?3:0);return total+(owner(p)===player?value:-value)},0)}function search(st,depth,alpha,beta){if(st.result||depth===0)return evaluate(st);const maximizing=st.turn===player;let best=maximizing?-Infinity:Infinity;for(const m of checkersMoves(st)){const next=checkersMove(st,m.from,m.to),v=search(next,depth-1,alpha,beta);best=maximizing?Math.max(best,v):Math.min(best,v);if(maximizing)alpha=Math.max(alpha,best);else beta=Math.min(beta,best);if(beta<=alpha)break}return best}const values=moves.map(m=>search(checkersMove(s,m.from,m.to),3,-Infinity,Infinity));const best=Math.max(...values);return pick(moves.filter((_,i)=>values[i]===best),rng)}

export const WORDS=[
{word:'CAT',picture:'🐱',clue:'A pet that says meow.',group:'Animals'}, {word:'DOG',picture:'🐶',clue:'A pet that says woof.',group:'Animals'}, {word:'PIG',picture:'🐷',clue:'A farm animal that says oink.',group:'Animals'}, {word:'HEN',picture:'🐔',clue:'A bird that lays eggs.',group:'Animals'}, {word:'COW',picture:'🐮',clue:'A farm animal that says moo.',group:'Animals'}, {word:'FOX',picture:'🦊',clue:'An animal with a bushy tail.',group:'Animals'}, {word:'BUG',picture:'🐞',clue:'A little creature with six legs.',group:'Animals'}, {word:'BEE',picture:'🐝',clue:'An insect that makes honey.',group:'Animals'}, {word:'BAT',picture:'🦇',clue:'An animal that flies at night.',group:'Animals'}, {word:'FISH',picture:'🐟',clue:'An animal that swims with fins.',group:'Animals'}, {word:'DUCK',picture:'🦆',clue:'A bird that says quack.',group:'Animals'}, {word:'FROG',picture:'🐸',clue:'An animal that hops and says ribbit.',group:'Animals'},
{word:'SUN',picture:'☀️',clue:'It shines in the sky in the daytime.',group:'Our world'}, {word:'MAP',picture:'🗺️',clue:'It shows where places are.',group:'Our world'}, {word:'BUS',picture:'🚌',clue:'A big vehicle with lots of seats.',group:'Our world'}, {word:'CAR',picture:'🚗',clue:'A vehicle with four wheels.',group:'Our world'}, {word:'HAT',picture:'👒',clue:'You wear this on your head.',group:'Our world'}, {word:'BED',picture:'🛏️',clue:'You sleep in this at night.',group:'Our world'}, {word:'CUP',picture:'🥤',clue:'You drink from this.',group:'Our world'}, {word:'BALL',picture:'⚽',clue:'You can kick or throw this.',group:'Our world'}, {word:'STAR',picture:'⭐',clue:'A tiny light you see in the night sky.',group:'Our world'}, {word:'BOAT',picture:'⛵',clue:'You ride in this on the water.',group:'Our world'},
{word:'EGG',picture:'🥚',clue:'A hen lays this.',group:'Food'}, {word:'JAM',picture:'🍓',clue:'A sweet fruit spread for toast.',group:'Food'}, {word:'NUT',picture:'🥜',clue:'A little food inside a hard shell.',group:'Food'}, {word:'HAM',picture:'🥪',clue:'A kind of meat you can put in a sandwich.',group:'Food'}, {word:'CAKE',picture:'🎂',clue:'A birthday treat with candles.',group:'Food'}, {word:'MILK',picture:'🥛',clue:'A white drink that can come from a cow.',group:'Food'}];
export function newWord(group='All',previous='',rng=Math.random){let choices=WORDS.filter(w=>(group==='All'||w.group===group)&&w.word!==previous);if(!choices.length)choices=WORDS;return{...pick(choices,rng),guesses:[],result:null,moves:0,custom:false}}
export function customWord(word){const cleaned=word.trim().toUpperCase();if(!/^[A-Z]{2,12}$/.test(cleaned))return null;return{word:cleaned,picture:'✦',clue:'A word picked just for you.',group:'Your word',guesses:[],result:null,moves:0,custom:true}}
export function wordMove(state,letter){if(state.result||!/^[A-Z]$/.test(letter)||state.guesses.includes(letter))return null;const s=copy(state);s.guesses.push(letter);s.moves++;const misses=s.guesses.filter(c=>!s.word.includes(c)).length;if([...s.word].every(c=>s.guesses.includes(c)))s.result={winner:1};else if(misses>=8)s.result={winner:2};return s}
